m: Portable Container\n-- Item Effect: Grant Portable container key item\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nlocal keyItemId = xi.keyItem.PORTABLE_CONTAINER\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasKeyItem(keyItemId) then\n        return xi.msg.basic.ALREADY_HAVE_KEY_ITEM, 0, keyItemId\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addKeyItem(keyItemId)\n    target:messageBasic(xi.msg.basic.OBTAINED_KEY_ITEM, xi.item.PORTABLE_CONTAINER, keyItemId)\nend\n\nreturn itemObject\n"},["scripts/items/porxie_quiver.lua"]={["Path"]="scripts/items/porxie_quiver.lua",["SHA256"]="5b0f944fd2733b192c38dfe738a8efc6183a028fc3d1be9568f4ed18fee7838c",["Text"]="-----------------------------------\n-- ID: 6414\n-- Porxie Quiver\n-- When used, you will obtain one stack of Porxie Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.PORXIE_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/pot-au-feu.lua"]={["Path"]="scripts/items/pot-au-feu.lua",["SHA256"]="01c9ba608383e7cb1b4f5a66547fa5845a9068488e42bd5268afab77108d5d18",["Text"]="-----------------------------------\n-- ID: 5752\n-- Item: Pot-au-feu\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Strength 3\n-- Agility 3\n-- Intelligence -3\n-- Ranged Attk % 15 Cap 60\n-- Ranged ACC % 10 Cap 50\n-- Enmity -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourc