 {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/potion.lua"]={["Path"]="scripts/items/potion.lua",["SHA256"]="104c77a89f6516b5c5fb04c24d9b8ebe5ade3005905ab82f6dc289beaf16a774",["Text"]="-----------------------------------\n-- ID: 4112\n-- Item: Potion\n-- Item Effect: Restores 50 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(50 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/potion_+1.lua"]={["Path"]="scripts/items/potion_+1.lua",["SHA256"]="907bc2cecadf7f220ce6d91aebfdd927e805f1b03bafec3ce88f5e990f71aa5d",["Text"]="-----------------------------------\n-- ID: 4113\n-- Item: Potion +1\n-- Item Effect: Restores 60 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(60 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/potion_+2.lua"]={["Path"]="scripts/items/potion_+2.lua",["SHA25