256"]="0beac5a4ba5e5514dfcfc78a23fb31e2ac4e11b9dbfaf43dc257aaae85b1b3c6",["Text"]="-----------------------------------\n-- ID: 5890\n-- Item: poultry_pitaru\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- MP +7% (cap 110)\n-- Increases rate of magic skill gains by 40%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 7)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 110)\n    effect:addMod(xi.mod.MAGIC_SKILLUP_RATE, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/powder_boots.lua"]={["Path"]="scripts/items/powder_boots.lua",["SHA256"]="c9428cf1ad1444b3a708c3eee21aae7ad3aba48996726f61ad2ebfbd8e6b216d",["Text"]="-----------------------------------\n-- ID: 15320\n-- Powder Boots\n--  Enchantment: \"Flee\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:delStatusEffect(xi.effect.FLEE)\n    target:addStatusEffect(xi.effect.FLEE, { power = 10000, duration = 30, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/praecipitatio_cell.lua"]={["Path"]="scripts/items/praecipitatio_cell.lua",["SHA256"]="f470befb2b9b754b95c05c28d1112ef26fdf237c8275a3c3eda2e4b76b831d08",["Text"]="-----------------------------------\n-- Praecipitatio Cell\n-- ID 5378\n-- Unlocks magic\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.OMERTA) then\n        return 0\n    end\n\n    return -1\nend\n\nitemObject.onItemUse = function(target)\n    target:delStatusEffectSilent(xi.effect.OMERTA)\n    target:messageText(target, zones[target:getZoneID()].text.CELL_OFFSET + 10)\n    if target:hasPet() then\n        target:getPet():delStatusEffectSilent(xi.effect.OMERTA)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/prime_angler_stewpot.lua"]={["Path"]="scripts/items/prime_angler_stewpot.lua",["SHA256"]="cd8cf093c05241037ba1111589b1cd2ceed04dd4937037860682386a20f5767a",["Text"]="-----------------------------------\n-- ID: 5612\n-- Item: Prime Angler Stewpot\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP +10% (cap 200)\n-- MP +15\n-- Dexterity 2\n-- Agility 1\n-- Mind 1\n-- HP Recovered while healing 7\n-- MP Recovered while healing 2\n-- Accuracy 15% Cap 30\n-- Ranged Accuracy 15% Cap 30\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 200)\n    effect:addMod(xi.mod.FOOD_MP, 15)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.MND, 1)\n    effect:addMod(xi.mod.HPHEAL, 7)\n    effect:addMod(xi.mod.MPHEAL, 2)\n    effect:addMod(xi.mod.FOOD_ACCP, 15)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 30)\n    effect:addMod(xi.mod.FOOD_RACCP, 15)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 30)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/prime_beef_stewpot.lua"]={["Path"]="scripts/items/prime_beef_stewpot.lua",["SHA256"]="b4baf43a8827a89b0469de1c93ef6c15093b571a7fc197f6bedcf2fe68e7441c",["Text"]="-----------------------------------\n-- ID: 5548\n-- Item: Prime Beef Stewpot\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP +10% Cap 75\n-- MP +15\n-- Strength +2\n-- Agility +1\n-- Mind +1\n-- HP Recovered while healing +7\n-- MP Recovered while healing +2\n-- Attack 18% Cap 60\n-- Evasion +6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 75)\n    effect:addMod(xi.mod.FOOD_MP, 15)\n    effect:addMod(xi.mod.STR, 2)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.MND, 1)\n    effect:addMod(xi.mod.HPHEAL, 7)\n    effect:addMod(xi.mod.MPHEAL, 2)\n    effect:addMod(xi.mod.FOOD_ATTP, 18)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 60)\n    effect:addMod(xi.mod.EVA, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/prime_crab_stewpot.lua"]={["Path"]="scripts/items/prime_crab_stewpot.lua",["SHA256"]="a3ff47729358d7ede3737fd6c63c8cf0cc115249e0c282ee5f12f1fdfc1049c7",["Text"]="-----------------------------------\n-- ID: 5545\n-- Item: Prime Crab Stewpot\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP +10% Cap 75\n-- MP +15\n-- Vitality +1\n-- Agility +1\n-- Mind +2\n-- HP Recov