rget, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 100)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.MND, 2)\n    effect:addMod(xi.mod.HPHEAL, 9)\n    effect:addMod(xi.mod.MPHEAL, 3)\n    effect:addMod(xi.mod.ACC, 7)\n    effect:addMod(xi.mod.RACC, 7)\n    effect:addMod(xi.mod.EVA, 7)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pro-ether.lua"]={["Path"]="scripts/items/pro-ether.lua",["SHA256"]="124b005ade47ed9cc86ce4d3d0db8113cfba1772483ecfd45da05ec396341faa",["Text"]="-----------------------------------\n-- ID: 4140\n-- Item: Pro-Ether\n-- Item Effect: Restores 250 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(250 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/pro-ether_+1.lua"]={["Path"]="scripts/items/pro-ether_+1.lua",["SHA256"]="08dd4f30b0fd1aeab2c4ab7b98761e3d5ce88fa6ecb12a37d3ab34ca03ef9c2d",["Text"]="-----------------------------------\n-- ID: 4141\n-- Item: Pro-Ether +1\n-- Item Effect: Restores 280 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(280 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/pro-ether_+2.lua"]={["Path"]="scripts/items/pro-ether_+2.lua",["SHA256"]="5a1c1a8f384ef03022093dae4eafbae5a134ccda13014b70598a4676aa14de02",["Text"]="-----------------------------------\n-- ID: 4142\n-- Item: Pro-Ether +2\n-- Item Effect: Restores 310 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(310 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/pro-ether_+3.lua"]={["Path"]="scripts/items/pro-ether_+3.lua",["SHA256"]="a70c995608847bf335ddedcd25f977a3a97b59fd6222fe6f46345a3b248d1827",["Text"]="-----------------------------------\n-- ID: 4143\n-- Item: Pro-Ether +3\n-- Item Effect: Restores 350 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(350 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/prominence_axe.lua"]={["Path"]="scripts/items/prominence_axe.lua",["SHA256"]="f8dc7c529103952842bbbba68531d0a7311c8dbb6506b811097d72190fdc524b",["Text"]="-----------------------------------\n-- ID: 18220\n-- Item: Prominence Axe\n-- Additional effect: fire damage\n-- Enchantment: Enfire\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 7,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENFIRE, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PROMINENCE_AXE) ~= nil then\n        target:delStatusEffect(xi.effect.ENFIRE, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PROMINENCE_AXE)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.PROMINENCE_AXE) then\n        target:addStatusEffect(xi.effect.ENFIRE, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.PROMINENCE_AXE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n\n    effect:addMod(xi.mod.ENSPELL, xi.element.FIRE)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- Empty function required for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/prominence_sword.lua"]={["Path"]="scripts/items/prominence_sword.lua",["SHA256"]="974481ea529474262072418c4ce5203016b5f5e4915353f2d2ec39ac384dfaa8",["Text"]="-----------------------------------\n-- ID: 18381\n-- Item: Prominence Sword\n-- Additional effect: fire damage\n-- Enchantment: Enfire\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 7,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENFIRE, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PROMINENCE_SWORD) ~= nil then\n        target:delStatusEffect(xi.effect.ENFIRE, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PROMINENCE_SWORD)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.PROMINENCE_SWORD) then\n        target:addStatusEffect(xi.effect.ENFIRE, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.PROMINENCE_SWORD })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n\n    effect:addMod(xi.mod.ENSPELL, xi.element.FIRE)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- Empty function required for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/protect_earring.lua"]={["Path"]="scripts/items/protect_earring.lua",["SHA256"]="6dadac666f1e99c0e7d5c9efd2aef43449b631f0b1a7b1f6e4ce4c8502df28d6",["Text"]="-----------------------------------\n-- ID: 15838\n-- Item: Protect Earring\n-- Item Effect: Protect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local power = 20\n    local tier = 1\n    local bonus = 0\n    if target:getMod(xi.mod.ENHANCES_PROT_SHELL_RCVD) > 0 then\n        bonus = 2 -- 2x Tier from MOD\n    end\n\n    power = power + (bonus * tier)\n\n    if target:addStatusEffect(xi.effect.PROTECT, { power = power, duration = 1800, origin = user, tier = tier }) then\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.PROTECT)\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/protect_ring.lua"]={["Path"]="scripts/items/protect_ring.lua",["SHA256"]="baa3830820439167ec4fa9d819856199071185047235b66bad05c22001d9f3a6",["Text"]="-----------------------------------\n-- ID: 15838\n-- Item: Protect Ring\n-- Item Effect: Protect II\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local power = 50\n    local tier = 2\n    local bonus = 0\n    if target:getMod(xi.mod.ENHANCES_PROT_SHELL_RCVD) > 0 then\n        bonus = 2 -- 2x Tier from MOD\n    end\n\n    power = power + (bonus * tier)\n\n    if target:addStatusEffect(xi.effect.PROTECT, { power = power, duration = 1800, origin = user, tier = tier }) then\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.PROTECT)\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/puffball.lua"]={["Path"]="scripts/items/puffball.lua",["SHA256"]="8313e5efa62024679e68d12a6657a10a27d4bad1d93bccacb1cafd0c6c294132",["Text"]="-----------------------------------\n-- ID: 4448\n-- Item: puffball\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Strength -4\n-- Mind 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -4)\n    effect:addMod(xi.mod.MND, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/puk_egg.lua"]={["Path"]="scripts/items/puk_egg.lua",["SHA256"]="dcddb397a6ee84101b1957a4c4347f35895daa4b45d7f8abe2baac707c05abcd",["Text"]="-----------------------------------\n-- ID: 5569\n-- Item: puk_egg\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Health 6\n-- Magic 6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 6)\n    effect:addMod(xi.mod.FOOD_MP, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pukatrice_egg.lua"]={["Path"]="scripts/items/pukatrice_egg.lua",["SHA256"]="991b81d092e68c2deb5bd94330d6fd4b6f4ede114ee6eb2cfa3875ad15754534",["Text"]="-----------------------------------\n-- ID: 6274\n-- Item: pukatrice_egg\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP +15\n-- MP +15\n-- STR +2\n-- Fire resistance +20\n-- Attack +20% (cap 85)\n-- Ranged Attack +20% (cap 85)\n-- Subtle Blow +8\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 15)\n    effect:addMod(xi.mod.FOOD_MP, 15)\n    effect:addMod(xi.mod.STR, 2)\n    effect:addMod(xi.mod.FIRE_MEVA, 20)\n    effect:addMod(xi.mod.FOOD_ATTP, 20)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 85)\n    effect:addMod(xi.mod.FOOD_RATTP, 20)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 85)\n    effect:addMod(xi.mod.SUBTLE_BLOW, 8)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pukatrice_egg_+1.lua"]={["Path"]="scripts/items/pukatrice_egg_+1.lua",["SHA256"]="dcbfa3ff396fe650629b075be36e2ee04aa07f662880ed9c0c84a81b798a0136",["Text"]="-----------------------------------\n-- ID: 6275\n-- Item: pukatrice_egg_+1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- HP +20\n-- MP +20\n-- STR +3\n-- Fire resistance +21\n-- Attack +21% (cap 90)\n-- Ranged Attack +21% (cap 90)\n-- Subtle Blow +9\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.STR, 3)\n    effect:addMod(xi.mod.FIRE_MEVA, 21)\n    effect:addMod(xi.mod.FOOD_ATTP, 21)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 90)\n    effect:addMod(xi.mod.FOOD_RATTP, 21)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 90)\n    effect:addMod(xi.mod.SUBTLE_BLOW, 9)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pumpkin_cake.lua"]={["Path"]="scripts/items/pumpkin_cake.lua",["SHA256"]="78ae505cfc89d2e2dab26a33426823f95f34a8dccf5266ff95029812d81dfb91",["Text"]="-----------------------------------\n-- ID: 5631\n-- Item: Pumpkin Cake\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP Recovered while healing +2\n-- MP Recovered while healing +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pumpkin_pie.lua"]={["Path"]="scripts/items/pumpkin_pie.lua",["SHA256"]="c54b1cf0a23c97b36a8263d161b22d2ad50469a73274cc9d4effb06aa6a7d512",["Text"]="-----------------------------------\n-- ID: 4446\n-- Item: pumpkin_pie\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Magic 40\n-- Agility -1\n-- Intelligence 3\n-- Charisma -2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 40)\n    effect:addMod(xi.mod.AGI, -1)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.CHR, -2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pumpkin_pie_+1.lua"]={["Path"]="scripts/items/pumpkin_pie_+1.lua",["SHA256"]="3ae094139122e71335524d24cf3b707d85dad796a83005bcb1879c157093d396",["Text"]="-----------------------------------\n-- ID: 4525\n-- Item: pumpkin_pie_+1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Magic 45\n-- Intelligence 4\n-- Charisma -1\n-- MP Recovered While Healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 45)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.CHR, -1)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/puppetmaster_die.lua"]={["Path"]="scripts/items/puppetmaster_die.lua",["SHA256"]="2e1cff99240032a083e5c51713b51906c4c912dd490bd536b382663d6bd8adcf",["Text"]="-----------------------------------\n-- ID: 5494\n-- Puppetmaster Die\n-- Teaches the job ability Puppet Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.PUPPET_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.PUPPET_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/purgatory_collar.lua"]={["Path"]="scripts/items/purgatory_collar.lua",["SHA256"]="fada4cfc07eecf9de22714f769b4df093c8b1eb1561f1ab3cf669f27a23e5d58",["Text"]="-----------------------------------\n-- ID: 15507\n-- Item: Purgatory Collar\n-- Item Effect: Conserve MP\n-- Duration: 45 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PURGATORY_COLLAR) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PURGATORY_COLLAR)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.PURGATORY_COLLAR) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 45, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.PURGATORY_COLLAR })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    -- **Power needs validation**\n    effect:addMod(xi.mod.CONSERVE_MP, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/purple_drop.lua"]={["Path"]="scripts/items/purple_drop.lua",["SHA256"]="3a9693f1f2c5232e5b7dff91604561602ed3c74e53e1882bd3f48b9f7dfb2840",["Text"]="-----------------------------------\n--  ID: 4262\n--  Item: Purple Drop\n--  Dexterity 5\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.DEX_BOOST, { power = 5, duration = 900, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/purple_polypore.lua"]={["Path"]="scripts/items/purple_polypore.lua",["SHA256"]="4280d8ed3fc29164870f08b0de22121ac7018ddba1ba3123e8b775fcdc47091f",["Text"]="-----------------------------------\n--  ID: 5682\n--  Item: Purple Polypore\n--  Food Effect: 5 Min, All Races\n-----------------------------------\n--  Strength -6\n--  Mind +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -6)\n    effect:addMod(xi.mod.MND, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pyrohelix_schema.lua"]={["Path"]="scripts/items/pyrohelix_schema.lua",["SHA256"]="b3fbeabd2fd66e0bcba98c35be4192aa75560a07f4721ba89e5698da90a15128",["Text"]="-----------------------------------\n-- ID: 6041\n-- Pyrohelix Schema\n-- Teaches the black magic Pyrohelix\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.PYROHELIX)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.PYROHELIX)\nend\n\nreturn itemObject\n"},["scripts/items/qiqirn_mine.lua"]={["Path"]="scripts/items/qiqirn_mine.lua",["SHA256"]="6faf950909ba18dcfa19f8152360728433abc2a2390f344ba25ef65bdb0c5c68",["Text"]="-----------------------------------\n-- ID: 5331\n-- Item: Qiqirn Mine\n-- When used, Summons a bomb to blowup a wall\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:getZoneID() ~= xi.zone.LEBROS_CAVERN then\n        result = 55\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local instance = target:getInstance()\n    if not instance then\n        return\n    end\n\n    local bomb = instance:insertAlly(100)\n    if not bomb then\n        return\n    end\n\n    local xPos = target:getXPos()\n    local zPos = target:getZPos()\n    local targ = target:getTarget()\n\n    if (xPos > 160 and xPos < 186) and (zPos > 359 and zPos < 380) then\n        bomb:setSpawn(178.608, -40.742, 376.904, 196)\n        bomb:spawn()\n    elseif (xPos > 250 and xPos < 264) and (zPos > 192 and zPos < 220) then\n        bomb:setSpawn(258.687, -30.805, 216.147, 190)\n        bomb:spawn()\n    elseif (xPos > 327 and xPos < 343) and (zPos > 278 and zPos < 300) then\n        bomb:setSpawn(338.272, -30.857, 296.276, 197)\n        bomb:spawn()\n    elseif (xPos > 298 and xPos < 320) and (zPos > 330 and zPos < 345) then\n        bomb:setSpawn(303.334, -30.026, 341.164, 167)\n        bomb:spawn()\n    else\n        bomb:setSpawn(xPos + math.randomInt(-2, 2), target:getYPos() , zPos + math.randomInt(-2, 2))\n        bomb:spawn()\n    end\n\n    bomb:setMobLevel(75)\n\n    if targ ~= nil then\n        bomb:updateEnmity(targ)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/quadav_belt.lua"]={["Path"]="scripts/items/quadav_belt.lua",["SHA256"]="7d3f6c9119042dd267214b22acf7f332d79670395cef9f6fe4e2b044443a0beb",["Text"]="-----------------------------------\n-- ID: 10848\n-- Quadav Belt\n-- Enchantment: 60Min, Costume - Quadav\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 644, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/queens_crown.lua"]={["Path"]="scripts/items/queens_crown.lua",["SHA256"]="396eecca7aea2f2c02771c07884224a4964574528ffea710b16b6c62e7bf66f5",["Text"]="-----------------------------------\n-- ID: 6064\n-- Item: queens_crown\n-- Food Effect: 240 Min, All Races\n-----------------------------------\n-- MP+6% (Upper limit 55)\n-- INT+4\n-- MND+3\n-- CHR+2\n-- STR-2\n-- MACC+4\n-- MAB+7\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 6)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 55)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.MND, 3)\n    effect:addMod(xi.mod.CHR, 2)\n    effect:addMod(xi.mod.STR, -2)\n    effect:addMod(xi.mod.MACC, 4)\n    effect:addMod(xi.mod.MATT, 7)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/quus.lua"]={["Path"]="scripts/items/quus.lua",["SHA256"]="e1096f01802d1f9d1751a8594c26ecb5ef31a9cfa4c30fadfae5ce4f0fe7ec00",["Text"]="-----------------------------------\n-- ID: 5793\n-- Item: quus\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/raaz_quiver.lua"]={["Path"]="scripts/items/raaz_quiver.lua",["SHA256"]="befea15c05ab13bd1bdcf4725dc94ac03a6672720cf382d940be671aa475f9bc",["Text"]="-----------------------------------\n-- ID: 6202\n-- Raaz Quiver\n-- When used, you will obtain one stack of Raaz Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.RAAZ_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/rabao_earring.lua"]={["Path"]="scripts/items/rabao_earring.lua",["SHA256"]="61bafd1d1535025b759efb141213d47dbe20d6fadd020a0ab047f0f636d4ae5e",["Text"]="-----------------------------------\n-- ID: 16045\n-- Rabao Earring\n-- Enchantment: \"Teleport\" (Rabao)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.RABAO_EARRING, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/rabbit_belt.lua"]={["Path"]="scripts/items/rabbit_belt.lua",["SHA256"]="f098acb39774f1396b9132e1502a25368148ae43f8d2c660120e53719f97c4d5",["Text"]="-----------------------------------\n-- ID: 15297\n-- Rabbit Belt\n-- Enchantment: 60Min, Costume - Rarab (brown)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 268, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/rabbit_cap.lua"]={["Path"]="scripts/items/rabbit_cap.lua",["SHA256"]="e760bcd8b951fc0ffa5b1f9ab7671059f2273594ce87bfc699a99a517dd20d14",["Text"]="-----------------------------------\n-- ID: 26788\n-- Item: Rabbit Cap\n-- When used, you will obtain 1-2 random initial eggs\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { math.randomInt(xi.item.A_EGG, xi.item.Z_EGG), 1 } })\n\n    if math.randomInt(1, 5) > 4 then\n        npcUtil.giveItem(target, { { math.randomInt(xi.item.A_EGG, xi.item.Z_EGG), 1 } })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/rabbit_pie.lua"]={["Path"]="scripts/items/rabbit_pie.lua",["SHA256"]="5522a31dc29702df5c03a93721defce2936395a7b3d6562921402d49b33560e7",["Text"]="-----------------------------------\n-- ID: 5685\n-- Item: rabbit_pie\n-- Food Effect: 30minutes, All Races\n-----------------------------------\n-- Strength 5\n-- Vitality 5\n-- Attack 25% (caps @ 100)\n-- Ranged Attack 25% (caps @ 100)\n-- Defense 25% (caps @ 100)\n-- Intelligence -2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 5)\n    effect:addMod(xi.mod.VIT, 5)\n    effect:addMod(xi.mod.FOOD_ATTP, 25)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 100)\n    effect:addMod(xi.mod.FOOD_RATTP, 25)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 100)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 100)\n    effect:addMod(xi.mod.INT, -2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/radiatus_cell.lua"]={["Path"]="scripts/items/radiatus_cell.lua",["SHA256"]="dafe104c22099ff113cba04f59b5941d5fdbd213b90cb7378450abc1cc48fd18",["Text"]="-----------------------------------\n-- Radiatus Cell\n-- ID 5368\n-- Unlocks hand equipment\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.ENCUMBRANCE_I, 0x0040)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.ENCUMBRANCE_I, 0x0040, 3)\nend\n\nreturn itemObject\n"}};
